uniform vec2 resolution;
uniform float time;

void main(void) {
    vec4 a[6];
    a[0] = vec4(1.0, 0.4, 0.4, 1.0);
    a[1] = vec4(0.4, 1.0, 0.4, 1.0);
    a[2] = vec4(0.9, 0.9, 0.4, 1.0);
    a[5] = vec4(0.7, 0.5, 1.0, 1.0);
    a[4] = vec4(0.3, 0.9, 0.9, 1.0);
    a[3] = vec4(1.0, 0.6, 0.4, 1.0);

    vec2 uv = gl_FragCoord.xy / resolution.xx;
    float xColumn = floor(uv.x * 10.0 - time);
    float offset = 6.0 * xColumn;
    float yColumn = floor((uv.y * 10.0 + time + xColumn)/2.0 + offset);
    float xBorder = step(0.2, mod(uv.x * 10.0 - time, 1.0));
    float yBorder = step(0.2, mod(uv.y * 10.0 + time + xColumn, 2.0));
    int colorIndex = int(mod(xColumn + yColumn, 6.0));

    gl_FragColor = xBorder * yBorder *
      vec4(1.0, 0.4, 0.2, 1.0) * mod(float(colorIndex + 1)/6.0 * gl_FragCoord.x/200.0, 1.0);
      //a[colorIndex];
