#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#else
precision mediump float;
#endif

uniform vec2 resolution;
uniform float time;

float rand(vec2 n) {return fract(sin(dot(n, vec2(12.9898, 4.1414))) * 43758.5453); }
float noisey(vec2 n) {return rand(floor(n)); }

void main(void) {
	float zoom = 100.0;

	float angle = 0.4;
	vec2 t_coord = vec2(
		(sin(angle) * gl_FragCoord.x + cos(angle) * gl_FragCoord.y),
	  (sin(angle) * gl_FragCoord.y - cos(angle) * gl_FragCoord.x) + time * 100.0
		)/zoom;

	float noise_val = noisey(t_coord);
	vec2 origin = floor(t_coord);

	origin = origin + vec2(1.0, 0.0) * step(noise_val, 0.5);
	origin = origin + vec2(0.0, 1.0) * step(mod(noise_val, 0.5), 0.25);

	float dist = distance(origin, t_coord);

	float shadow_val = clamp(mod((1.0 - t_coord.x)*2.0, 2.0) + 0.3, 0.0, 1.0);

	noise_val = mod(noise_val, 0.25)*4.0;

	float desx = step(noise_val, 0.95);
	float variance = (1.0 - noise_val)*15.0;
	vec4 col =
		vec4(noise_val*0.5, noise_val, 0.0, 1.0) * desx +
		vec4(1.0, 0.7 - variance, variance, 1.0) * (1.0 - desx);

	gl_FragColor = col * step(dist, 1.0) * shadow_val;
}

#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#else
precision mediump float;
#endif

uniform vec2 resolution;
uniform float time;

const float pi = 3.14159265;
const int amount = 40;

float pointDistance(vec3 pos) {
	return pow(clamp(1.0 - length((gl_FragCoord.xy - pos.xy) / pos.z), 0.0, 1.0), 2.0);
}

void main(void) {

  float t = time/2.0 + 20.0;
  float brightness = 0.0;
  float size = 140.0;

	for(int i = 0; i < amount; i ++) {
		float n = float(i) / float(amount);
		float x = mod(200.0 * t * sin(2.0 * pi * n+ 0.15), resolution.x*1.4) - resolution.x * 0.2;
		float y = mod(200.0 * t * cos(2.0 * pi * n), resolution.y*1.4) - resolution.y * 0.2;
		if(distance(vec2(x, y), gl_FragCoord.xy) > 3.0 * size) continue;
		float s = size * (2.0 + cos(2.0 * pi * n));
		float d = pointDistance(vec3(x, y, s));
	  brightness += d;
		if (brightness >= 1.0) break;
	}
	gl_FragColor = vec4(0.8, 0.8, 0.0, 1.0) * (step(0.5, brightness) + brightness*1.5) + vec4(0.5, 0.0, 0.5, 1.0);
}

#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#else
precision mediump float;
#endif

uniform float time;
uniform vec2 resolution;

float inCircle(float n, float o, float r) {
	float angle = 2.4 * n + time/10.0;
	vec2 circle = resolution/2.0 + sqrt(n) * o * vec2(sin(angle), cos(angle));
	return distance(gl_FragCoord.xy, circle);
}

void main(void) {
    vec2 center = resolution / 2.0;
    gl_FragColor = vec4(0.0, 0.4, 0.0, 1.0);

    float amount = 200.0;
    float t_amount = mod(floor(time*30.0), amount * 2.0);
    t_amount += step(amount, t_amount) * 2.0 * (amount - t_amount);

    float o = 55.0;
    float r = 80.0;
    float d = distance(gl_FragCoord.xy, center);

    float mini = floor(max(pow((d-r)/o, 2.0)-1.0,0.0));
    float maxi = ceil(min(pow((d+r)/o, 2.0),t_amount));

    const int MAX_ITER = 300; // must be >= possible maxi
    for(int i = 0; i < MAX_ITER; i++) {
        if(float(i) < mini) continue;
        if(float(i) >= maxi) break;
        float a = inCircle(float(i), o, r)/r;
        float b = float(i)/amount/2.0+0.5;
        if(a < 1.0) {
            gl_FragColor = vec4(1.0, 1.0-b, b, 1.0) * (0.9 + a);
            break;
        }
    }
}

#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#else
precision mediump float;
#endif

uniform vec2 resolution;
uniform float time;

const float size = 20.0;
const float angle = 0.5;
const vec4 color = vec4(1.0, 0.0, 0.7, 1.0);

const float pi = 3.14159265335;
const float scale = 100.0;
const int octaves = 1;
const float persistance = 0.5;
const float lacunarity = 0.5;

float rand(vec2 n) {return fract(sin(dot(n, vec2(12.9898, 4.1414))) * 43758.5453);}

float perlin(vec2 pos) {
	float cScale = scale;
	float cAmplitude = 1.0;
	float layeredPV = 0.0;
	float cV[4];
	float a; float b;
	for(int i = 0; i < octaves; i++) {
		for(int vertex = 1; vertex < 5; vertex ++) {
			vec2 vertexOffset = vec2(mod(float(vertex + 1), 2.0), floor(float(vertex) / 3.0));
      float gradAngle = 2.0 * pi * rand(floor(vec2(pos/cScale)) + vertexOffset);
      float gradX = sin(gradAngle);
      float gradY = cos(gradAngle);
      float oX = floor(pos.x/cScale) + float((mod(float(vertex), 2.0) == 0.0));
      float oY = floor(pos.y/cScale) + float(vertex > 2);
      oX = (pos.x - oX * cScale) / cScale;
      oY = (pos.y - oY * cScale) / cScale;
      if(vertex == 1) {
      	a = pow(oX, 3.0) * (oX * (oX * 6.0 - 15.0) + 10.0);
      	b = pow(oY, 3.0) * (oY * (oY * 6.0 - 15.0) + 10.0);
      }
      cV[vertex - 1] = gradX * oX + gradY * oY;
		}
		layeredPV += cAmplitude * ((1.0 - b) * ((1.0 - a) * cV[0] + a * cV[1]) + b * ((1.0 - a) * cV[2] + a * cV[3]));
		cAmplitude *= persistance;
		cScale *= lacunarity;
	}
	return layeredPV;
}

float ontrack(vec2 uv, vec4 p) {
	float type;
	vec2 corner;
	if(p == vec4(0.0)) return 0.0;
	if(length(p) == 1.0){
		type = 0.0;
		if (p.x == 1.0) corner = vec2(1.0, 0.0);
		if (p.y == 1.0) corner = vec2(1.0, 1.0);
		if (p.z == 1.0) corner = vec2(0.0, 1.0);
		if (p.w == 1.0) corner = vec2(0.0, 0.0);
	} else if (length(p) == length(vec2(1.0))) {
		if(p == vec4(1.0, 0.0, 1.0, 0.0)) {type = 1.0; corner = vec2(0.0, 1.0);}
		else if(p == vec4(0.0, 1.0, 0.0, 1.0)) {type = 1.0; corner = vec2(0.0, 0.0);}
		else {
			type = 2.0;
			if(p.x == 1.0) {
				if(p.y == 1.0) {
					corner = vec2(1.0, 0.0);
				} else {
					corner = vec2(0.0, 0.0);
				}
			} else {
				if(p.y == 1.0) {
					corner = vec2(1.0, 1.0);
				} else {
					corner = vec2(0.0, 1.0);
				}
			}
		}
	} else if(length(p) == length(vec3(1.0))) {
		type = 3.0;
		if (p.x == 0.0) corner = vec2(0.0, 0.0);
		if (p.y == 0.0) corner = vec2(1.0, 0.0);
		if (p.z == 0.0) corner = vec2(1.0, 1.0);
		if (p.w == 0.0) corner = vec2(0.0, 1.0);
	} else {
		type = 4.0;
	}
	float sv = mod(corner.x + corner.y, 2.0);
  vec2 r_uv = (uv.xy * (1.0 - sv) + uv.yx * sv) * (-2.0 * corner + vec2(1.0)) + corner;
	if(type == 0.0) {
		if(r_uv.y < 0.5) return 1.0 - distance(r_uv.x, 0.5) * 2.0;
		else return max(1.0 - distance(r_uv, vec2(0.5)) * 2.0, 0.0);
	} else if (type == 1.0) {
  	return 1.0 - distance(r_uv.x, 0.5) * 2.0;
  } else if(type == 2.0) {
    float dist = distance(r_uv, vec2(0.0)) * 2.0;
    dist += 2.0 * (step(1.0, dist) * -dist + step(1.0, dist));
    return max(dist, 0.0);
  } else if (type == 3.0) {
  	if(r_uv.x < 0.5) return 1.0 - distance(r_uv.x, 0.5) * 2.0;
  	else return 1.0 - min(distance(r_uv.x, 0.5), distance(r_uv.y, 0.5)) * 2.0;
  } else {
  	return 1.0 - min(distance(r_uv.x, 0.5), distance(r_uv.y, 0.5)) * 2.0;
  }
}

vec4 getFormAt(vec2 pos) {
	float aV = clamp(perlin(floor(pos)) * 0.6 + 0.8, 0.0, 1.0);
	float r = rand(floor(pos));
	vec4 outputs = vec4(0.0);
	if(mod(r,1.0) > aV) outputs.x = 1.0; r = mod(r * 2.0, 1.0);
	if(mod(r,1.0) > aV) outputs.y = 1.0; r = mod(r * 2.0, 1.0);
	if(mod(r,1.0) > aV) outputs.z = 1.0; r = mod(r * 2.0, 1.0);
	if(mod(r,1.0) > aV) outputs.w = 1.0; r = mod(r * 2.0, 1.0);
  return outputs;
}

void main(void) {
	float depth = max((resolution.y/1.5 - gl_FragCoord.y) / 1000.0, 0.0);
	vec2 p = gl_FragCoord.xy / depth + vec2(-100.0, 300.0) * time;
	p = vec2(sin(angle) * p.x + cos(angle) * p.y, sin(angle) * p.y - cos(angle) * p.x)/size;

  float trackValue;

	if(mod(floor(p.x) + floor(p.y), 2.0) == 1.0) {
	  trackValue = ontrack(vec2(mod(p.x, 1.0), mod(p.y, 1.0)), getFormAt(p));
  } else {
  	vec4 form = vec4(0.0);

  	form.x = getFormAt(p + vec2(-1.0, 0.0)).z;
  	form.y = getFormAt(p + vec2(0.0, 1.0)).w;
  	form.z = getFormAt(p + vec2(1.0, 0.0)).x;
  	form.w = getFormAt(p + vec2(0.0, -1.0)).y;

  	trackValue = ontrack(vec2(mod(p.x, 1.0), mod(p.y, 1.0)), form);
  }
  trackValue = trackValue * 2.0;
  trackValue += (log(depth) / 1.5);
  gl_FragColor = vec4(trackValue - 1.5, trackValue - 1.5, trackValue, 0.0);
}

