uniform vec2 resolution;
uniform float time;

const float size = 100.0;
const float scale = 10.0;
const int octaves = 1;
const float persistance = 0.5;
const float lacunarity = 0.5;
const float pi = 3.14159265;

float rand(vec2 n) {return fract(sin(dot(n, vec2(12.9898, 4.1414))) * 43758.5453);}
float perlin(vec2 pos) {
	float cScale = scale;
	float cAmplitude = 1.0;
	float layeredPV = 0.0;
	float cV[4];
	vec2 a;
	for(int i = 0; i < octaves; i++) {
		for(int vertex = 0; vertex < 4; vertex ++) {
			vec2 vertexOffset = vec2(mod(float(vertex), 2.0), floor(float(vertex) / 2.0));
      float gradAngle = 2.0 * pi * rand(floor(pos/cScale) + vertexOffset);
      vec2 g = vec2(sin(gradAngle), cos(gradAngle));
      vec2 o = floor(pos/cScale) + vertexOffset;
      o = (pos - o * cScale) / cScale;
      if(vertex == 0) {
      	a = o * o * o * (o * (o * 6.0 - 15.0) + 10.0);
      }
      cV[vertex] = dot(g, o);
		}
		layeredPV += cAmplitude * mix(mix(cV[0], cV[1], a.x), mix(cV[2], cV[3], a.x), a.y);
		cAmplitude *= persistance;
		cScale *= lacunarity;
	}
	return layeredPV;
}

vec2 rotateVec(vec2 v, float a) {
	float b = -a / 180.0 * 3.1415926;
	return vec2(sin(b) * v.x + cos(b) * v.y, cos(b) * v.x - sin(b) * v.y);
}

void main(void) {
	vec2 pos = gl_FragCoord.xy/size;
	vec2 vertex = floor(pos + vec2(0.5));
	float dis = distance(vertex, pos);
	float pV = perlin(rotateVec(pos, time*10.0) + vec2(time)) * 3.0;
	int cV = int(clamp(pV * dis * 8.0 + 2.0, 0.0, 3.0));

	vec3 color;
	if(cV == 0) color = vec3(0.0, 0.0, 0.0);
	else if(cV == 1) color = vec3(1.0, 0.2, 0.0);
	else if(cV == 2) color = vec3(0.0, 0.9, 1.0);
	else color = vec3(1.0, 1.0, 1.0);

	gl_FragColor = vec4(color, 1.0);
}

#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#else
precision mediump float;
#endif

uniform vec2 resolution;
uniform float time;

const float cellSize = 100.0;
const float frequency = 1.0;
const float colorOffset = 0.1;

float round(float v){return floor(v + 0.5);}
vec2 round(vec2 v){return vec2(round(v.x), round(v.y));}

vec2 rotateVec(vec2 v, float a) {
	float b = -a / 180.0 * 3.1415926;
	return vec2(sin(b) * v.x + cos(b) * v.y, cos(b) * v.x - sin(b) * v.y);
}

void main(void) {
	float t = sin(time)*2.0;
	vec2 coord = rotateVec((gl_FragCoord.xy - resolution/2.0) / cellSize, 10.0 * time);
	vec2 cell = round(coord);
	float cellDist = length(cell);
	float cellB1 = sin(cellDist/frequency * t) + 1.3;
	float cellB2 = sin(cellDist/frequency * t + colorOffset) + 1.3;

	float fragDist = distance(cell, coord) * 1.414;

	float step1 = step(cellB1, fragDist);
	float step2 = step(cellB2, fragDist);


	gl_FragColor = vec4(step1, step2, step2, 1.0);
}

#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#else
precision mediump float;
#endif

uniform vec2 resolution;
uniform float time;
uniform sampler2D world1;
uniform sampler2D world2;

const float pi = 3.14159;
const float radius = 500.0;
const float sun = -100.0;
const float fov = 0.0;
const vec4 atmosphere = vec4(0.2, 0.5, 1.0, 1.0) * 0.4;
const float sunSpeed = 1.0;
const float earthSpeed = 0.1;

vec2 rotateVec(vec2 v, float a) {
	float b = -a / 180.0 * 3.1415926;
	return vec2(cos(b) * v.x + sin(b) * v.y, cos(b) * v.y - sin(b) * v.x);
}

float getAngle(vec2 c) {
	float angle = atan(c.y / c.x) + pi/2.0;
  if(c.x < 0.0) angle += + pi;
	return angle;
}

void main(void) {
	vec2 center = resolution/2.0;
	vec2 coord = (gl_FragCoord.xy - center) / radius;
	vec2 rotatedCoord = rotateVec(coord, -23.5);

	float dist = length(coord);
	float f = getAngle(coord);
	float sunRadian = mod(sun / 180.0 * pi + time * sunSpeed + pi, 2.0 * pi) - pi;


	if(dist > 1.0) {
		//is atmosphere or space
		float sunFactor = sin(f) * -sin(sunRadian) + cos(sunRadian) * 0.4;
	  gl_FragColor = atmosphere * 3.0 * sunFactor * clamp(1.0 - (dist - 1.0) * 18.0, 0.0, 1.0);
	} else {
		float d = asin(dist) * (180.0 - fov) / 180.0;
		float e = getAngle(rotatedCoord);

		float latitude = asin(sin(d) * cos(e));
		float longitude = mod(atan(tan(d) * sin(e)) + time * earthSpeed, 2.0 * pi);

		float sunLat = asin(sin(d) * cos(f));
		float sunLong = atan(tan(d) * sin(f)) + sunRadian;
		sunLong = mod(sunLong + pi, 2.0 * pi) - pi;

		vec3 sampleVec;
		float x = longitude/pi;
		float y = -sin(latitude) / 2.3 + 0.5;
    if (longitude <= pi) sampleVec = texture2D(world1, vec2(x, y)).rgb;
    else sampleVec = texture2D(world2, vec2(x - 1.0, y)).rgb;

    float diffuse = cos(sunLong) * cos(sunLat) * 1.5;

    vec2 specCenter = vec2(sunRadian / 2.0, 0.0);
    float specDist = distance(specCenter, vec2(sunLong, sunLat));
    vec4 specular = vec4(0.0);

    float blueThresh = sampleVec.z - (sampleVec.x + sampleVec.y) * 0.5;

    if(blueThresh > 0.0) specular = vec4(1.0, 0.9, 0.5, 1.0) * 0.7 * clamp(0.035 / specDist - 0.1, 0.0, 1.0);

		gl_FragColor = (vec4(sampleVec, 1.0) + atmosphere) * diffuse + specular;
	}
}

