uniform vec2 resolution;
uniform float time;

const float pi = 3.14159265;
const int amount = 30;

float bounce(float value, float period) {
	float r = mod(value, 2.0 * period);
	return period -abs(period - r);
}

void main(void) {

	vec2 center = resolution/2.0;
	float minDist = 10000.0;
	float ccv;
	for(int i = 0; i < amount; i ++) {
		float value = float(i)/float(amount);
		float vertexAngle = value * 0.5 * pi;
		float t = time * 100.0 + 20000.0;
		vec2 vertexpos = vec2(bounce(sin(vertexAngle) * t + center.x, resolution.x), bounce(cos(vertexAngle) * t + center.y, resolution.y));
		value = vertexpos.x/resolution.x + vertexpos.y/resolution.y;
		float dist = distance(gl_FragCoord.xy, vertexpos);
		if(dist < minDist) {
			minDist = dist;
			ccv = value;
		}
	}
	float intervals = 3.0;
	ccv = bounce(ccv*intervals, 1.0) * 0.5 + 0.25;
	gl_FragColor = vec4(ccv, 0.0, 1.0-ccv, 1.0);
	//gl_FragColor = vec4(0.0, 1.0 - minDist/ 300.0, 1.0, 1.0);
}

