precision highp float;
#else
precision mediump float;
#endif

uniform vec2 resolution;
uniform float time;

const float camHeight = 40.0;
const float duneHeight = 30.0;

const float pi = 3.14159265359;

const float lacunarity = 0.5;
const float persistance = 0.5;

vec2 rotateVec(vec2 v, float b) {
    return vec2(cos(b) * v.x + sin(b) * v.y, cos(b) * v.y - sin(b) * v.x);
}

float rand(vec2 n) {return fract(sin(dot(n, vec2(12.9898, 4.1414))) * 43758.5453);}

float noize(vec2 pos) {
    return mix(
        mix(rand(floor(pos)), rand(vec2(ceil(pos.x), floor(pos.y))), fract(pos.x)),
        mix(rand(vec2(floor(pos.x), ceil(pos.y))), rand(ceil(pos)), fract(pos.x)),
        fract(pos.y)
    );
}

float layeredNoize(vec2 pos, int octaves, float scale) {
    pos = pos/scale;
    float layered = 0.0;
    const int MAX_OCTAVES = 10;
    for(int layer = 1; layer <= MAX_OCTAVES; layer++) {
        if(layer > octaves) break;
        pos = rotateVec(pos/lacunarity, 2.4);
        layered += noize(pos) * pow(persistance, float(layer));
    }
    return layered;
}

vec3 getColor(float height) {
    if(height > 0.7) return vec3(0.8, 0.8, 0.8);
    if(height > 0.65) return vec3(0.55, 0.5, 0.4);
    height /= 0.65;
    return vec3(0.8-height, 0.6, height* 0.1);
}

void main(void) {
    vec2 center = resolution * 0.5;
    float maxi = max(center.x, center.y);
    vec2 sightVec = (gl_FragCoord.xy - center)/maxi - vec2(0.0, 0.0);

    float zIntersec = (camHeight-duneHeight)/-sightVec.y;
    if(zIntersec <= 0.0) {
        gl_FragColor = vec4(0.4, 0.6, 1.0, 1.0);
    } else {
        float t = time * 10.0;
        vec3 samplePos = vec3(0.0, camHeight, 0.0);
        float sampleHeight = 0.0;

        const int MAX_STEPS = 20;
        for(int counter = 0; counter < MAX_STEPS; counter++) {
            samplePos = vec3(sightVec.x * zIntersec, camHeight + sightVec.y * zIntersec, zIntersec + t);
            sampleHeight = layeredNoize(samplePos.xz, 7, 50.0) * duneHeight;
            if(abs(samplePos.y - sampleHeight) <= 0.2) break;
            zIntersec += (samplePos.y - sampleHeight) * sqrt(zIntersec/50.0);
        }

        float sampleOffset = layeredNoize(samplePos.xz + vec2(0.001, -0.0005), 7, 50.0) * duneHeight;
        float difference = (sampleHeight - sampleOffset)*200.0;
        float rnd = 0.5 * (layeredNoize(samplePos.xy + vec2(200.0, 300.0), 2, 50.0) - 0.5);

        gl_FragColor = vec4(getColor(sampleHeight/ duneHeight + rnd), 1.0) * ((difference + 0.8) * (sampleHeight/duneHeight + 0.1));
    }
}

