float rand(vec2 n) {return fract(sin(dot(n, vec2(12.9898, 4.1414))) * 43758.5453);}

vec4 interpolateColors(float v) {
	return
	step(abs(v - 0.5), 0.5) * vec4(53, 80, 112, 1.0) +
	step(abs(v - 1.5), 0.5) * vec4(109, 89, 122, 1.0) +
	step(abs(v - 2.5), 0.5) * vec4(181, 101, 118, 1.0) +
	step(abs(v - 3.5), 0.5) * vec4(229, 117, 111, 1.0) +
	step(abs(v - 4.5), 0.5) * vec4(234, 172, 139, 1.0);
}

vec3 triHeight(vec2 coord) {
	coord.y /= 0.8660254;
	coord.x  = coord.x - 0.5 * coord.y;
	vec2 cellCoord = floor(coord) * vec2(2.0, 1.0);
	cellCoord += vec2(cellCoord.y, 0.0);
	vec2 iCC = mod(coord, 1.0);
	if(step(1.0, iCC.x + iCC.y) == 1.0) {
		iCC = 1.0 - iCC;
		cellCoord += vec2(1.0, 0.0);
	}
	float height;
	vec2 ab = vec2(min(iCC.x, iCC.y), max(iCC.x, iCC.y));
	if(2.0 * ab.x + ab.y > 1.0) return vec3(3.0 * (1.0 - (ab.x + ab.y)), cellCoord);
	else return vec3(3.0 * ab.x, cellCoord);
}

void main(void) {
	float t = time/3.0;
	vec3 tH = triHeight(gl_FragCoord.xy/200.0);
	float value = mod((tH.x + t - tH.y/20.0) * 1.5, 5.0);
	gl_FragColor = interpolateColors(value) / 255.0;
}

