uniform vec2 resolution;
uniform float time;

vec2 rotateVec(vec2 v, float b) {
	return vec2(cos(b) * v.x + sin(b) * v.y, cos(b) * v.y - sin(b) * v.x);
}

bool inSierpinsky(vec2 pos, float t) {
    const int maxSteps = 32;
    int limit = int(11.0 + t * 4.0);
    int counter = 0;
    for(int i = 0; i < maxSteps; i++) {
        if(!(pos.x + pos.y < 1.0 && counter < limit)) break;
        pos = mod(pos * 2.0, 1.0);
        counter++;
    }
    return (pos.x + pos.y < 1.0);
}

float timedSierpinsky(vec2 pos, float t) {
	float maxi = max(resolution.x, resolution.y);
	pos = (pos - resolution/2.0) / maxi / 2.0;
	pos /= pow(2.0, t * 4.0);
	pos = rotateVec(pos, t * 2.0943951);
	pos.x *= 0.8660254;
	pos += 1.142857143 * vec2(1.0, 1.0)/2.0;
	pos.x -= pos.y * 0.5;
	return float(inSierpinsky(pos, t));
}

void main(void) {
	vec2 pos = gl_FragCoord.xy;
	float t = mod(time / 10.0, 1.0);

	float sum = timedSierpinsky(pos, t);

	gl_FragColor = vec4(sum) * (1.0 - 0.1 * mod(t*4.0, 1.0));
}

