float rand(vec2 n) {return fract(sin(dot(n, vec2(12.9898, 4.1414))) * 43758.5453);}

vec2 rotateVec(vec2 v, float b) {
    return vec2(cos(b) * v.x + sin(b) * v.y, cos(b) * v.y - sin(b) * v.x);
}

vec4 get(vec2 coord) {
    return texture2D(backbuffer, coord/resolution);
}

bool getFractal(vec2 pos, float t, vec4 modify){
    const int MAX_ITER = 100;
    int limit = int(12.0 + t * 8.0);
    for(int i = 0; i < MAX_ITER; i ++) {
        if(i >= limit) break;
        pos *= 2.0;
        if(pos.x < 1.0){
            if(pos.y < 1.0){
                return false;
            } else {
                pos = vec2(mod(pos.y, 1.0), mod(-pos.x, 1.0));
            }
        } else {
            if(pos.y < 1.0){
                pos = vec2(mod(pos.x * modify.x, 1.0), mod(pos.y * modify.y, 1.0));
            } else {
                pos = vec2(mod(pos.x * modify.z, 1.0), mod(pos.y * modify.w, 1.0));
            }
        }
    }
    if(pos.x < 0.5 && pos.y < 0.5) return false;
    else return true;
}

vec2 transformPos(vec2 pos, float zoom, float t, float maxi) {
    pos = (pos - resolution / 2.0) / (2.0 * maxi) / zoom;
    pos = rotateVec(pos, -t * 2.0 * 6.2831853);
    pos += vec2(0.2, 0.6);
    return pos;
}

void main(void) {
    float maxi = max(resolution.x, resolution.y);
    float t = mod(time / 30.0, 1.0);
    float zoom = pow(2.0, t * 8.0);
    vec2 pos = gl_FragCoord.xy;

    pos = transformPos(pos, zoom, t, maxi);

    float modTimer = mod(time / 50.0, 1.0);
    vec4 modifier = vec4(
        step(1.0, mod(modTimer * 16.0, 2.0)),
        step(1.0, mod(modTimer * 8.0, 2.0)),
        step(1.0, mod(modTimer * 4.0, 2.0)),
        step(1.0, mod(modTimer * 2.0, 2.0))
    );
    modifier = modifier * 2.0 - 1.0;
    modifier = vec4(-1.0, 1.0, -1.0, -1.0);

    bool onFractal = getFractal(pos, t, modifier);
    if(onFractal) { 
        gl_FragColor = vec4(1.0, 0.0, 0.5, 1.0); 
        return;
    } else {
        gl_FragColor = vec4(1.0);
        vec4 sampleColor;
        float r = 20.0 * rand(pos * 2.0) + 20.0;
        const int MAX_R = 64;
        for(int i = 1; i < MAX_R; i ++) {
            if(i >= int(r)) break;
            if(gl_FragCoord.x + float(i) > resolution.x || gl_FragCoord.y + float(i) > resolution.y) return;
            sampleColor = get(gl_FragCoord.xy + vec2(float(i)));
            if(sampleColor.r - sampleColor.g > 0.9) {
                gl_FragColor = 0.5 * (1.0 - float(i) / r) * vec4(1.0, 0.0, 0.5, 1.0);
                if(i > int(r - 2.0)) {gl_FragColor = vec4(1.0, 0.0, 0.5, 1.0);}
                break;
            }
        }
    }
    if(time < 0.1) gl_FragColor = vec4(1.0);
}

