        if(i >= limit) break;
        pos *= 3.0;
        if(pos.x < 1.0){
            if(pos.y < 1.0) {
                continue;
            } else if(pos.y < 2.0) {
                pos = vec2(fract(-pos.x), fract(pos.y));
            } else {
                return false;
            }
        } else if(pos.x < 2.0) {
            if(pos.y < 1.0){
                pos = vec2(fract(-pos.x), fract(-pos.y));
            } else if(pos.y < 2.0) {
                pos = vec2(fract(-pos.y), fract(pos.x));
            } else {
                return false;
            }
        } else {
            if(pos.y < 1.0){
                return false;
            } else if(pos.y < 2.0) {
                pos = vec2(fract(pos.x), fract(pos.y));
            } else {
                return false;
            }
        }
    }
    return true;
}

