	vec2 pos = gl_FragCoord.xy;
	float f = float(frame);
	float timeStamp = floor(f/i);
	vec3 crack = vec3(resolution.x/4.0 + (resolution.x / 2.0) * rand(vec2(timeStamp, 3.5*timeStamp)), resolution.y / 4.0 + (resolution.y / 2.0) * rand(vec2(timeStamp*4.7, timeStamp*7.15)), pi * rand(vec2(timeStamp*0.67, timeStamp*13.52)));

	vec2 dist = rotateVec(pos - crack.xy, -crack.z);
