const float pi = 3.14159265359;

const float scale = 500.0;
const int octaves = 1;
const float persistance = 0.5;
const float lacunarity = 0.5;

float rand(vec2 n) {return fract(sin(dot(n, vec2(12.9898, 4.1414))) * 43758.5453);}

float perlin(vec2 pos) {
	float cScale = scale;
	float cAmplitude = 1.0;
	float layeredPV = 0.0;
	float cV[4];
	vec2 a;
	for(int i = 0; i < octaves; i++) {
		for(int vertex = 0; vertex < 4; vertex ++) {
			vec2 vertexOffset = vec2(mod(float(vertex), 2.0), floor(float(vertex) / 2.0));
      float gradAngle = 2.0 * pi * rand(floor(pos/cScale) + vertexOffset);
      vec2 g = vec2(sin(gradAngle), cos(gradAngle));
      vec2 o = floor(pos/cScale) + vertexOffset;
      o = (pos - o * cScale) / cScale;
      if(vertex == 0) {
      	a = o * o * o * (o * (o * 6.0 - 15.0) + 10.0);
      }
      cV[vertex] = dot(g, o);
		}
		layeredPV += cAmplitude * mix(mix(cV[0], cV[1], a.x), mix(cV[2], cV[3], a.x), a.y);
		cAmplitude *= persistance;
		cScale *= lacunarity;
	}
	return layeredPV;
}

vec2 rotateVec(vec2 v, float b) {
	return vec2(cos(b) * v.x + sin(b) * v.y, cos(b) * v.y - sin(b) * v.x);
}

vec4 get(vec2 coord) {
coord = mod(coord, resolution);
	return texture2D(backbuffer, coord/resolution);
}

void main(void) {
	vec2 pos = gl_FragCoord.xy;
	if(frame == 0) {
		gl_FragColor = vec4(rand(pos + daytime.z), rand(pos + daytime.y), rand(pos + daytime.x), 1.0); //20.0 * (perlin(pos, 5.0) + 0.1));
	} else {
		float t = time * 2.0;
		vec2 offset = 20.0 * rotateVec(vec2(0.0, rand(pos)), 3.0 * pi * perlin(pos + t + daytime.x * 60.0));
		vec4 last = get(pos);
		vec4 change = 0.05 * (get(pos + offset) - vec4(vec3(0.5), 0.0));
		gl_FragColor = vec4(last.r + change.g, last.g + change.b, last.b - change.r, 1.0);
	}
}

precision highp float;

uniform vec2 resolution;
uniform float time;

const int iterations = 500;
const float speed = 1.0;

float sigmoid(float x, float steepness) {
    float offset = 0.5;
    float scale = 1.0 / (1.0 + exp(-steepness * (x - offset)));
    float normalized = (scale - scale * exp(-steepness)) /(1.0 - exp(-steepness));
    return normalized;
}

vec2 getOffset(int idx) {
	if(idx == 0) return vec2(-0.818128, 0.1988497);
	else if(idx == 1) return vec2(-0.743643887037151, 0.131825904205330);
	else if(idx == 2) return vec2(-1.62916, -0.020635);
	else if(idx == 3) return vec2(-0.761574, -0.0847596);
	else if(idx == 4) return vec2(0.2599, 0.0019);
	else if(idx == 5) return vec2(0.0, -0.6358);
	else if(idx == 6) return vec2(0.099937, 0.640075);
	else return vec2(0.0578, -0.65655);
}

vec2 offset() {
    float tp = 6.283185307179;
    float t = time / speed / tp;

