	float cScale = scale;
	float cAmplitude = 1.0;
	float layeredPV = 0.0;
	float cV[8];
	vec3 a;
	for(int i = 0; i < octaves; i++) {
		for(int vertex = 0; vertex < 8; vertex ++) {
			vec3 vertexOffset = vec3(mod(float(vertex), 2.0), mod(floor(float(vertex) / 2.0), 2.0), floor(float(vertex) / 4.0));
      float gradYaw = 2.0 * pi * rand(floor(pos/cScale + 91.0) + vertexOffset);
      float gradPitch = pi * rand(floor(pos/cScale) + vertexOffset);
      vec3 g = vec3(sin(gradYaw) * cos(gradPitch), sin(gradYaw) * sin(gradPitch), cos(gradYaw));
      vec3 o = floor(pos/cScale) + vertexOffset;
      o = (pos - o * cScale) / cScale;
      if(vertex == 0) {
      	a = o * o * o * (o * (o * 6.0 - 15.0) + 10.0);
      }
      cV[vertex] = dot(g, o);
		}
		layeredPV += cAmplitude * mix(mix(mix(cV[0], cV[1], a.x), mix(cV[2], cV[3], a.x), a.y), mix(mix(cV[4], cV[5], a.x), mix(cV[6], cV[7], a.x), a.y), a.z);
		cAmplitude *= persistance;
		cScale *= lacunarity;
	}
	return layeredPV;
