	float dist = distance(gl_FragCoord.xy, resolution/2.);
	float pv = perlin3d(vec3(gl_FragCoord.xy, time * 50.));
	float pat = (sin(gl_FragCoord.x / 4.) + sin(gl_FragCoord.y / 4.))/4. + 0.5;
