	float layered = 0.0;
	for(int layer = 1; layer <= octaves; layer ++) {
    layered += noize3d(pos) * pow(persistance, float(layer));
    pos = rotateVec3(pos/lacunarity, 2.4, 1.7);
	}
	return layered;
}

vec3 LN3DD(vec3 pos) {
	float offset = 0.001;
	float a = layeredNoize3d(pos);
	float x = layeredNoize3d(pos + vec3(offset, 0., 0.));
	float y = layeredNoize3d(pos + vec3(0., offset, 0.));
	return vec3(a/1000., a-x, a-y) * 1000.;
}

void main(void) {
	vec3 deriv = LN3DD(vec3(gl_FragCoord.xy/50., time*0.5));
	vec2 dir = touch - gl_FragCoord.xy;
	float dist = length(dir);
	dir /= dist;
	dist += 10.;

  float intens = dot(deriv.yz, dir)/dist*100. + deriv.x*0.3;
	gl_FragColor = vec4(deriv.x + intens, vec3(max(0., intens)));
}

