uniform int frame;

const int iterations = 50;

vec2 rotateVec(vec2 v, float b) {
	return vec2(cos(b) * v.x + sin(b) * v.y, cos(b) * v.y - sin(b) * v.x);
}

vec2 compSqrt(vec2 c) {
    float x2 = c.x * c.x;
    float y2 = c.y * c.y;
    return vec2(x2 - y2, 2.0 * c.x * c.y);
}

vec2 mandelbrot(vec2 c, float zoom) {
	float x = c.x - 0.25;
  float y2 = c.y * c.y;
  float q = x * x + y2;
  if (q * (q + x) < 0.25 * y2) return vec2(0.0, iterations);
  if ((c.x + 1.0) * (c.x + 1.0) + y2 < 0.0625) return vec2(0.0, iterations);

  vec2 z = c;
	const int MAX_ITER = 500;
	int j = 0;
	for(int i = 0; i < MAX_ITER; i++) {
			z = compSqrt(z);
			z += c;
			if(dot(z, z) > 4.0) return vec2(10.0, i);
			j = i;
	}
	return vec2(length(z), j);
}

void main(void) {
	float t = time + date.z + date.y;
	vec2 pos = (gl_FragCoord.xy - resolution/2.) * 1.4;
	float mdb;
	if(frame == 0) {
		mdb = mandelbrot(-pos.yx / 300. + vec2(-0.6, 0.), 500.).y / float(iterations);
	} else {
		mdb = texture2D(backbuffer, gl_FragCoord.xy/resolution).w;
	}
	float l = length(pos);
	if(l >= 500.) {
		pos = normalize(pos) * 498.;
	} else {
		l = 300.;
	}
  vec3 s = vec3(2.718, 1.732, 1.414) * 0.3;
  float r = rotateVec(pos, s.r * t).y/1000. + 0.5;
  float g = rotateVec(pos, s.g * t).y/1000. + 0.5;
  float b = rotateVec(pos, s.b * t).y/1000. + 0.5;
  vec4 col = vec4(r, g, b, 1.) / l * 300.;
  float br = 1. + mdb;
	gl_FragColor = col * br;
	gl_FragColor.w = mdb;
}

