		float h = max(0., 1. / l - 0.2);
		h_sum += h;
		v_sum += v * h;
	}
	h_sum = (h_sum - 0.5) * 3.;
	if(h_sum > 0.){
		float bh = h_sum / (h_sum + 1.);
		vec3 nv = vec3(v_sum * (1. - bh), 0.);
		nv.z = sqrt(1. - pow(nv.x, 2.) - pow(nv.y, 2.));
	  gl_FragColor = tex(uv + nv.xy * 0.4);
	}
}

