const int octaves = 3;
const float lacunarity = 0.5;
const float persistance = 0.5;

float rand(vec3 n) {return fract(sin(dot(n, vec3(12.9898, 4.1414, 7.8931))) * 43758.5453);}
vec3 rotateVec3(vec3 v, float yaw, float pitch) {
    float cy = cos(yaw);
    float sy = sin(yaw);
    vec3 yawRotated = vec3(
        cy * v.x - sy * v.z,
        v.y,
        sy * v.x + cy * v.z
    );

    float cp = cos(pitch);
    float sp = sin(pitch);
    vec3 pitchRotated = vec3(
        yawRotated.x,
        cp * yawRotated.y - sp * yawRotated.z,
        sp * yawRotated.y + cp * yawRotated.z
    );

    return pitchRotated;
}

float noize3d(vec3 pos) {
	return
	mix(
	  mix(
	  	mix(rand(floor(pos)),rand(vec3(ceil(pos.x), floor(pos.yz))),fract(pos.x)),
  	  mix(rand(vec3(floor(pos.x), ceil(pos.y), floor(pos.z))),rand(vec3(ceil(pos.xy), floor(pos.z))),fract(pos.x)),
  		fract(pos.y)
  	), mix(
	  	mix(rand(vec3(floor(pos.xy), ceil(pos.z))),rand(vec3(ceil(pos.x), floor(pos.y), ceil(pos.z))),fract(pos.x)),
	  	mix(rand(vec3(floor(pos.x), ceil(pos.yz))),rand(vec3(ceil(pos))),fract(pos.x)),
	  	fract(pos.y)
  	),
  	fract(pos.z)
  );
}

float layeredNoize3d(vec3 pos) {
	pos = rotateVec3(pos, 2.4, 1.7);
	float layered = 0.0;
	for(int layer = 1; layer <= octaves; layer ++) {
    layered += noize3d(pos) * pow(persistance, float(layer));
    pos = rotateVec3(pos/lacunarity, 2.4, 1.7);
	}
	return layered;
}

void main(void) {
	float cam_z = time * 10.;
	float z_flr = ceil(cam_z);
	float z_off = fract(cam_z);
	vec2 uv = (gl_FragCoord.xy - resolution/2.) / resolution.y * 16.;

  float dens = 0.;
	for(float i = 1.; i < 30.; i ++) {
		float cam_rel_z = (1. - z_off) + i;
		vec3 cam_rel_pos = vec3(uv, 1) * cam_rel_z;
		vec3 abs_pos = cam_rel_pos + vec3(0., 0., cam_z);
	  vec3 sam_pos = floor(abs_pos) + 0.5;
	  sam_pos.z = abs_pos.z;
    float d = distance(sam_pos, abs_pos);
    if(mod(sam_pos.z, 5.) == 0.) {
    	dens = max(0., layeredNoize3d(sam_pos / (vec3(1.) * 50.)) - 0.25);
    	float bright = min(1., 1. - abs(cam_rel_z - 15.) / 15.);
			gl_FragColor += vec4(0.1, 0., 0.3, 0.) * 2. * dens * bright;
		}
		gl_FragColor += step(rand(sam_pos), 0.02 * (dens - 0.1)) * vec4(max(0., 0.05 / d - 0.1));
	}
}

