uniform vec2 resolution;
uniform float time;

const float pi = 3.1415926;
const float FOV = 10.;
const float sectors = 3.;
const float layers = 15.;

float getAngle(vec2 c) {
	float angle = atan(c.y / c.x) / (2.0*pi)+ 0.25;
  if(c.x < 0.0) angle = angle + 0.5;
	return angle * pi * -2. + pi;
}

vec2 rotateVec(vec2 v, float b) {
	return vec2(cos(b) * v.x + sin(b) * v.y, cos(b) * v.y - sin(b) * v.x);
}

float distSegm(vec2 v1, vec2 v2, vec2 pos) {
  vec2 vc = v2-v1;
  vec2 vcp = pos-v1;
  float angle = getAngle(vc);
  vcp = rotateVec(vcp, -angle);
  if(vcp.y > 0. && vcp.y < length(vc)) {
  	return abs(vcp.x);
  } else if (vcp.y <= 0.) {
  	return distance(v1, pos);
  } else {
  	return distance(v2, pos);
  }
	return 1.;
}

vec4 colorr(float i) {
	i = i * 5. + time;
	return normalize( 0.5 + 0.5 * vec4(cos(i * -0.853 + 5.62), cos(i * 0.258), cos(i * 0.587 - 8.725), 0.));
}

void main(void) {
	vec3 cam = vec3(0., 0., time * 1.57);
	vec2 uv = (gl_FragCoord.xy - resolution/2.) / resolution.x * FOV;
	float z_flr = ceil(cam.z);
	float z_off = fract(cam.z);
	for(float i = 1.; i < layers; i ++) {
		float cam_rel_z = i - z_off;
		float abs_z = cam_rel_z + cam.z;

		vec2 uv_r = rotateVec(uv, sin(time/4.) * sin(abs_z));

		vec3 sam_pos = vec3(uv_r, 1.) * cam_rel_z - vec3(cam.xy, 0.);
		float norm_z = cam_rel_z/layers;
		float brightness = min(1., max(0., 1. - cam_rel_z / (layers - 1.)));
		brightness -= max(0., 1. - cam_rel_z);
		float r_x = 2.;
		vec4 color = vec4(1., 0.2, norm_z, 0.);
    for(float j = 0.; j < sectors; j ++) {
    	float angle = j * 2. * pi / sectors;
    	vec2 v1 = rotateVec(vec2(r_x, -1.), angle);
      vec2 v2 = rotateVec(vec2(r_x, 1.), angle);
    	gl_FragColor += colorr(abs_z/10.) / (distSegm(v1, v2, sam_pos.xy) * 20.) * brightness;
    }
	}
}

