const float scale = 30.;

float rand(vec2 n) {return fract(sin(dot(n, vec2(12.9898, 4.1414))) * 43758.5453);}

float char(vec2 pos, int c) {
	pos = pos * 2. - 1.;
	pos *= 1.1;
	if(c == 0) {
		pos *= vec2(1.5, 1.);
	  return step(length(pos), 1.) - step(length(pos * vec2(1.2, 1.15)), 1.) * step(0.13, abs(pos.x - pos.y));
	} else if(c == 1) {
		return max(0., min(1.,
		  step(abs(pos.y + 0.935), 0.065) * step(abs(pos.x), 0.5) +
			step(abs(pos.x), 0.065) * step(abs(pos.y), 1.) +
			step(abs(pos.x + 0.285), 0.22) * step(abs(pos.x - pos.y * 2. + 1.915), 0.15)
		));
	}
}

void main(void) {
	for(float z = 1.; z < 5.; z ++) {
    vec2 pos = gl_FragCoord.xy / scale * z;
    vec2 l_pos = fract(pos);
    vec2 sam = floor(pos);
    float period = rand(vec2(sam.x * z, 25.)) * 20.;
    float t = time + 100.;
    float b = 1. - (sam.y/20. + t)/ period;
    gl_FragColor += vec4(0., 1., 0., 0.) * max(0., char(l_pos, int(step(0.5, rand(sam + floor(b))))) * fract(b) / z);
  }
}

