vec4 hexHeight(vec2 coord) {
	coord.y /= 0.8660254;
	coord.x  = coord.x - 0.5 * coord.y;
	vec2 cellCoord = floor(coord);
	int cellType = int(mod(cellCoord.x - cellCoord.y, 3.0));
	vec2 iCC = mod(coord, 1.0);
	int halfIndex = int(step(1.0, iCC.x + iCC.y));
	vec2 center;
	if(cellType == 0){
		center = cellCoord + vec2(1.0, 0.0);
		if(halfIndex == 0) {
			return vec4(iCC.x, center, 5.0);
		} else {
			return vec4(1.0 - iCC.y, center, 0.0);
	  }
	} else if(cellType == 1) {
		if(halfIndex == 0) {
			center = cellCoord;
			return vec4(1.0 - iCC.x - iCC.y, center, 1.0);
		} else {
			center = cellCoord + vec2(1.0, 1.0);
			return vec4(iCC.x + iCC.y - 1.0, center, 4.0);
		}
	} else {
		center = cellCoord + vec2(0.0, 1.0);
		if(halfIndex == 0) {
			return vec4(iCC.y, center, 3.0);
		} else {
			return vec4(1.0 - iCC.x, center, 2.0);
		}
	}
}

void main(void) {
	vec3 light = normalize(vec3((touch - gl_FragCoord.xy)/resolution * 2., 0.5));
	vec2 pos = gl_FragCoord.xy/50. - 10.;
	vec4 hh = hexHeight(pos);
	vec2 hexCenter = hh.yz;
	hexCenter.x = hexCenter.x + 0.5 * hexCenter.y;
	hexCenter.y *= 0.8660254;
	vec3 nv = normalize(vec3(pos - hexCenter, 1.));
  float d = dot(light, nv);
	gl_FragColor = vec4(1.) * d / (acos(d)* 5.);
}

