precision highp float;
#else
precision mediump float;
#endif

uniform vec2 resolution;
uniform float time;

vec2 uv;
vec4 nv;
float size = 60.;
float FOV = 2.;
vec4 light1c = vec4(1., 0., 0.2, 0.);
vec3 light1p = vec3(2., -0.5, 0.);
vec4 light2c = vec4(0., 0.8, 1., 0.);
vec3 light2p = vec3(-2., -0.5, 0.);
vec4 light3c = vec4(0.2, 0.3, 0.4, 0.);
vec3 light3p = vec3(0., -4., -1.);

vec3 cube(float v) {
    return vec3(mod(v, 2.), floor(mod(v/2., 2.)), floor(mod(v/4., 2.))) * 2. - 1.;
}

vec3 rotateVec3(vec3 v, float yaw, float pitch, float roll) {
  // Yaw rotation (around Y-axis)
  float cy = cos(yaw);
  float sy = sin(yaw);
  vec3 yawRotated = vec3(
    cy * v.x - sy * v.z,
    v.y,
    sy * v.x + cy * v.z
  );

  // Pitch rotation (around X-axis)
  float cp = cos(pitch);
  float sp = sin(pitch);
  vec3 pitchRotated = vec3(
    yawRotated.x,
    cp * yawRotated.y - sp * yawRotated.z,
    sp * yawRotated.y + cp * yawRotated.z
  );

  // Roll rotation (around Z-axis)
  float cr = cos(roll);
  float sr = sin(roll);
  vec3 rollRotated = vec3(
    cr * pitchRotated.x + sr * pitchRotated.y,
    -sr * pitchRotated.x + cr * pitchRotated.y,
    pitchRotated.z
  );

  return rollRotated;
}

bool isPointOnRight(vec2 v1, vec2 v2, vec2 p) {
  vec2 d1 = v2 - v1; // Vector from v1 to v2
  vec2 d2 = p - v1;  // Vector from v1 to p
  float cross = d1.x * d2.y - d1.y * d2.x;
  return cross < 0.0;
}

void getNv(vec3 p1, vec3 p2, vec3 p3) {
  vec3 v1 = p2 - p1;
  vec3 v2 = p3 - p1;
  vec3 normal = normalize(cross(v1, v2));
  if (dot(normal, normal) < 1e-6 || abs(normal.z) < 1e-6) {
    nv = vec4(normal, 0.);
    return;
  }
  float d = -dot(normal, p1);
  float z = (normal.x * uv.x + normal.y * uv.y + d) / normal.z;
  nv = vec4(normal, z);
}

// Function to get vertex by index
vec3 getVertex(int index, vec2 cc) {
    return rotateVec3(
        cube(float(index)), 
        time + cc.x,
        time/3. + cc.y - cc.x,
        sin(time + cc.x + cc.y)
    );
}

bool inSq(int v1, int v2, int v3, int v4, vec2 cc) {
    vec3 vert0 = getVertex(v1, cc);
    vec3 vert1 = getVertex(v2, cc);
    vec3 vert2 = getVertex(v3, cc);
    vec3 vert3 = getVertex(v4, cc);

    // Check if point is inside quad
    if(!isPointOnRight(vert0.xy, vert1.xy, uv)) return false;
    if(!isPointOnRight(vert1.xy, vert2.xy, uv)) return false;
    if(!isPointOnRight(vert2.xy, vert3.xy, uv)) return false;
    if(!isPointOnRight(vert3.xy, vert0.xy, uv)) return false;

    getNv(vert0, vert1, vert2);
    return true;
}

void main(void) {
    uv = (mod(gl_FragCoord.xy/size, 2.) - vec2(1.)) * FOV;
    vec2 cc = floor(gl_FragCoord.xy/size/2.);

    if(inSq(0, 1, 3, 2, cc) || inSq(0, 2, 6, 4, cc) || inSq(5, 7, 3, 1, cc) || 
       inSq(4, 6, 7, 5, cc) || inSq(5, 1, 0, 4, cc) || inSq(3, 7, 6, 2, cc)) {
        gl_FragColor =
            light1c * (max(0., dot(nv.xyz, normalize(light1p))) + 0.1) +
            light2c * (max(0., dot(nv.xyz, normalize(light2p))) + 0.1) +
            light3c * (max(0., dot(nv.xyz, normalize(light3p))) + 0.3);
    } else {
        gl_FragColor = vec4(0., 0., 0., 1.); // Black background
    }
}

