float letter(float i, vec2 uv) {
    if(fract(uv) != uv) { return 0.; }
    i = floor(i);
    float y = (7. - floor(i/16.))/8.;
    float x = mod(i, 16.)/16.;
    uv /= vec2(16., 8.);
    uv += vec2(x, y);
    return texture2D(font, uv).r;
}

const float scale = 35.0;
const int octaves = 2;
const float persistance = 0.5;
const float lacunarity = 0.5;
const float pi = 3.1415926;

float rand(vec3 n) {
    return fract(sin(dot(n, vec3(12.9898, 4.1414, 7.8931))) * 43758.5453);
}

float perlin3d(vec3 pos) {
    float cScale = scale;
    float cAmplitude = 1.0;
    float layeredPV = 0.0;
    float cV[8];
    vec3 a;

    for(int i = 0; i < octaves; i++) {
        for(int vertex = 0; vertex < 8; vertex++) {
            vec3 vertexOffset = vec3(mod(float(vertex), 2.0), mod(floor(float(vertex) / 2.0), 2.0), floor(float(vertex) / 4.0));
            float gradYaw = 2.0 * pi * rand(floor(pos/cScale + 91.0) + vertexOffset);
            float gradPitch = pi * rand(floor(pos/cScale) + vertexOffset);
            vec3 g = vec3(sin(gradYaw) * cos(gradPitch), sin(gradYaw) * sin(gradPitch), cos(gradYaw));
            vec3 o = floor(pos/cScale) + vertexOffset;
            o = (pos - o * cScale) / cScale;
            if(vertex == 0) {
                a = o * o * o * (o * (o * 6.0 - 15.0) + 10.0);
            }
            cV[vertex] = dot(g, o);
        }
        layeredPV += cAmplitude * mix(mix(mix(cV[0], cV[1], a.x), mix(cV[2], cV[3], a.x), a.y), mix(mix(cV[4], cV[5], a.x), mix(cV[6], cV[7], a.x), a.y), a.z);
        cAmplitude *= persistance;
        cScale *= lacunarity;
    }
    return layeredPV;
}

vec3 color(float i) {
    i = i * 5. + time;
    return normalize(0.5 + 0.5 * vec3(cos(i * -0.853 + 5.62), cos(i * 0.258), cos(i * 0.587 - 8.725)));
}

void main(void) {
    vec2 uv = gl_FragCoord.xy / resolution.x * 150. / vec2(1., 2.);
    int p = int(max(min((perlin3d(vec3(floor(uv) * vec2(1., 2.), time * 3.)) + 0.5) * 32., 31.), 0.));
    gl_FragColor = vec4(color(float(p) / 200.) * (float(p)/64. + 0.5) * letter(float(getGradient(p)), fract(uv)), 1.0);
}

