    return vec2(cos(b) * v.x + sin(b) * v.y, cos(b) * v.y - sin(b) * v.x);
}

vec3 rainbow(float v) {
    float pi_2_3 = 2.0943951024;
    v *= 3. * pi_2_3;
    return vec3(cos(v), cos(v + pi_2_3), cos(v + 2. * pi_2_3)) * 0.5 + 0.5;
}

void main(void) {
    float pow_t = pow(2., fract(time));
    vec2 uv = rotateVec((gl_FragCoord.xy - resolution.xy/2. + 200. * vec2(sin(time), cos(time))) / resolution.x, time / 5.) * 2.;
    vec3 color = vec3(0.0);

    for(float i = 1.; i <= depth; i += 1.) {
        float d = i - pow_t;
        float p = pow(2., i);
        vec2 r_uv = roundVec(uv / pow_t * p) / p * pow_t;
        if(min(abs(uv.x - r_uv.x), abs(uv.y - r_uv.y)) < 0.003) {
            color += rainbow((time)/ 10.) * ((depth - d) / depth);
            break;
        }
    }

    gl_FragColor = vec4(color, 1.0);
}

