      	uv = rotateVec3(vec3(dot(v, uv), cross(v, uv)), t, i * 10.);
      }

      // Use conditional assignment instead of array indexing
      float intensity = 1. / length(uv);
      if (c < 0.5) {
      	color.r = intensity;
      } else if (c < 1.5) {
      	color.g = intensity;
      } else {
      	color.b = intensity;
      }
    }

    gl_FragColor = vec4(color, 1.0);
}

