	return vec2(cos(b) * v.x + sin(b) * v.y, cos(b) * v.y - sin(b) * v.x);
}

vec3 rotateVec(vec3 v, float yaw, float pitch) {
  float cy = cos(yaw);
  float sy = sin(yaw);
  vec3 yawRotated = vec3(
    cy * v.x - sy * v.z,
    v.y,
    sy * v.x + cy * v.z
  );

  float cp = cos(pitch);
  float sp = sin(pitch);
  vec3 pitchRotated = vec3(
    yawRotated.x,
    cp * yawRotated.y - sp * yawRotated.z,
    sp * yawRotated.y + cp * yawRotated.z
  );

  return pitchRotated;
}

float rand(vec2 n) {return fract(sin(dot(n, vec2(12.9898, 4.1414))) * 43758.5453);}
float noize(vec2 pos) {
	return mix(
		mix(rand(floor(pos)), rand(vec2(ceil(pos.x), floor(pos.y))), fract(pos.x)),
		mix(rand(vec2(floor(pos.x), ceil(pos.y))), rand(ceil(pos)), fract(pos.x)),
	  fract(pos.y)
	);
}

float layeredNoize(vec2 pos) {
	pos = rotateVec(pos, 2.4);
	float layered = 0.0;
	for(int layer = 1; layer <= octaves; layer ++) {
    layered += noize(pos) * pow(persistance, float(layer));
    pos = rotateVec(pos/lacunarity, 2.4);
	}
	return layered;
}

const float s = 0.85;
const float speed = 1.;
void main(void) {
	float t = time * speed;
	vec2 normCoord = (gl_FragCoord.xy - resolution.xy / 2.) / (resolution.x/2.);
	float d = - log(length(normCoord)) + 1.;
	float a = atan(normCoord.x, normCoord.y);
	float d2 = d / 2.;
	float h, h2;
	for(float i = 0.; i < 12.; i ++) {
		float delta = 0.25 / pow(2., i);
	  h = 1. - s * layeredNoize(vec2(cos(a * 2.) * 0.5, d2 + t));
	  h2 = d2 / d;
	  if(i > 8.) break;
	  if (h > h2) {
	  	d2 += delta * d;
	  } else {
	  	d2 -= delta * d;
	  }
	}
	float c = (1. - h) / s;
	float bb = texture2D(backbuffer, gl_FragCoord.xy / resolution).w;
	float o = max(0., min(bb - d2, 0.01) / speed * 20. / d2 - 0.2);
	float t2 = time / 5.;
	vec3 color1 = rotateVec(vec3(0.5, 0., 0.), (cos(t2) + 1.) * PI / 4., (sin(t2) - 1.) * PI / 4.);
	vec3 color2 = rotateVec(vec3(1., 0., 0.), (sin(t2) + 1.) * PI / 4., (cos(t2) - 1.) * PI / 4.);
	vec3 color = (color1 * (1. - c) + color2 * (c)) * (0.7 + o + c * 0.5);
	gl_FragColor = vec4(color / (d2 + 1.) * 1.5 + 0.1, d2);
}

