	vec2 uvr = rotateVec(uv, angle);
  float height = cos(time * speed + angle) * 100.;
  float z = -height / uvr.y;
  float v;
  if(z > 0.) {
    float x = uvr.x * z;
    //laser rays
    v += max(0., sqrt(noize(vec2(floor(x / 50.), time))));
    //fog effect
    v *= max(0., layeredNoize3d(vec3(uv, z/1000.) * 5.));
