const float PI = 3.1415926;

float funnel(vec3 p) {
	float r = length(p.xz);
  r = max(r, 0.001); // log stabilisieren
  return p.y - log(r);
}

void main(void){
    vec2 uv = (gl_FragCoord.xy - resolution / 2.)/ min(resolution.x, resolution.y) * 2.;

    float t = time * 0.5;
    vec2 uvt = (touch - resolution.x / 4.)/ resolution.x * 2.;


    // Kamera
    vec3 ro = vec3(0.0 - uvt.x, 2.0 + uvt.y * 2.5, -2.0 - uvt.y * 1.8); // leicht erhöht, damit man was sieht

    float pitch = uvt.y * 0.15 - 0.6;

    // Rotationsmatrix X-Achse
    mat3 rotX = mat3(
    1, 0, 0,
    0, cos(pitch), -sin(pitch),
    0, sin(pitch), cos(pitch)
    );

    // Ray
    vec3 rd = normalize(vec3(uv, 1.5));
    rd = rotX * rd;

    // --- Raymarching ---
    float tg = 0.0;
    float hit = -1.0;

    for(int i = 0; i < 100; i++) {
        vec3 p = ro + rd * tg;
        float d = funnel(p);

        if(abs(d) < 0.001) {
            hit = tg;
            break;
        }

        tg += d * (gl_FragCoord.y / resolution.y + 0.1);

        if(tg > 50.0) {break;}
    }

    // --- Farbe ---
    vec3 col = vec3(0.0);

    if(hit > 0.0) {
      vec3 p = ro + rd * hit;
      float angle = atan(p.x, p.z) / PI / 2.;
      float dist = length(p.xz);
      float shade = (p.y + 2.) * 0.3;

      col = vec3(1.) * shade * mod(floor(angle * 16. + t) + floor((sqrt(dist) + p.y) * 2. + t * 3.), 2.);
    } else if(uv.y > -0.1){
    	col = vec3(0., 0.5, 1.);
    }

    gl_FragColor = vec4(col, 1.0);
}

