vec3 hash33(vec3 p)
{
    p = fract(p * vec3(0.1031, 0.1030, 0.0973));
    p += dot(p, p.yzx + 33.33);
    return fract((p.xxy + p.yxx) * p.zyx);
}

vec3 grad(float f) {
	f *= 1.5;
	return 0.5 * vec3(
		sin(f * 0.7 + 0.7), -cos(f), sin(f + 2.)
	) + 0.5;
}

float obj(vec3 p, float t) {
	p = vec3(rotateVec(p.xy, (p.z) * rot), p.z);
	p = fract(p);
  return min(
  	min(
  	distance(p, vec3(0.5)) - 0.15,
  	distance(p.xy, vec2(0.5))- 0.05
  	), min(
  	distance(p.yz, vec2(0.5))- 0.05,
  	distance(p.zx, vec2(0.5))- 0.05
  	)
  );
}

