    float t2 = t * (PI/4. - rot);
    vec2 tc = vec2(sin(t2), cos(t2));
    vec3 ro = vec3(tc.x, tc.y, t);
    float pitch = 0.0;

    // Rotationsmatrix X-Achse
    mat3 rotX = mat3(
    1, 0, 0,
    0, cos(pitch), -sin(pitch),
    0, sin(pitch), cos(pitch)
    );

    // Ray
    vec3 rd = normalize(vec3(uv, 1.5));
    rd = rotX * rd;

    // --- Raymarching ---
    float tg = 0.0;
    float hit = -1.0;

    for(int i = 0; i < 100; i++) {
        vec3 p = ro + rd * tg;
        float d = obj(p, t);

        if(abs(d) < 0.001) {
            hit = tg;
            break;
        }

        tg += d * 0.7;

        if(tg > 50.0) {break;}
    }

    // --- Farbe ---
    vec3 col = vec3(0.0);

    if(hit > 0.0) {
      vec3 p = ro + rd * hit;
      p.xy = rotateVec(p.xy, p.z * rot);
      vec3 p2 = p - vec3(0., 0., t);
