const float PI = 3.1415926;

float smin( float a, float b, float k ) { k *= 4.0; float h = max( k-abs(a-b), 0.0 )/k; return min(a,b) - h*h*k*(1.0/4.0); }
// Scene SDF: three perpendicular cylinders of radius 0.1, smoothed together + tiled
float obj(vec3 p)
{
    p = fract(p);  // repeat every 1 unit

    float d1 = length(p.xy - 0.5) - 0.1;  // cylinder along z
    float d2 = length(p.xz - 0.5) - 0.1;  // cylinder along y
    float d3 = length(p.yz - 0.5) - 0.1;  // cylinder along x

    return smin(d1, smin(d2, d3, 0.1), 0.1);
}

// Compute surface normal from SDF (gradient approximation)
// Recommended version (4 evaluations, very common in Shadertoy/Inigo Quilez style)
vec3 getNormal(vec3 p)
{
    const float eps = 0.001;           // smaller = sharper, but can be noisy
    const vec2 h = vec2(eps, 0.0);

    vec3 n = vec3(
        obj(p + h.xyy) - obj(p - h.xyy),
        obj(p + h.yxy) - obj(p - h.yxy),
        obj(p + h.yyx) - obj(p - h.yyx)
    );

    return normalize(n);
}

void main()
{
    vec2 uv = (gl_FragCoord.xy - resolution.xy * 0.5) / resolution.x * 2.0;

    // Camera
    vec3 ro = vec3(0.0, 0.0, time);
    float pitch = 0.0;

    mat3 rotX = mat3(
        1.0, 0.0, 0.0,
        0.0, cos(pitch), -sin(pitch),
        0.0, sin(pitch), cos(pitch)
    );

    vec3 rd = normalize(vec3(uv, 1.5));
    rd = rotX * rd;

    float t = time * PI /4.;
    vec3 light = vec3(1.3 * vec2(sin(t), cos(t)), 2. + time);
    vec2 light2D = light.xy/(light.z - ro.z);

    // Raymarching
    float tg = 0.0;
    float hit = -1.0;

    for(int i = 0; i < 100; i++)
    {
        vec3 p = ro + rd * tg;
        float d = obj(p);

        if(abs(d) < 0.001)
        {
            hit = tg;
            break;
        }

        tg += d;
        if(tg > 50.0) break;
    }

    // Coloring
    vec4 col = vec4(0.0);
    if(hit > 0.0)
    {
        vec3 p = ro + rd * hit;
        vec3 n = getNormal(p);
        // Light setup
        vec3 lightVec = light - p;
        vec3 lightDir = normalize(lightVec);

        // Diffuse
        float dist = length(lightVec);
        float diffuse = max(dot(n, lightDir), 0.0) / (dist * 0.3 + 1.0);

        // Specular (Blinn-Phong)
        vec3 viewDir = normalize(ro - p);                    // direction to camera
        vec3 halfDir = normalize(lightDir + viewDir);
        float specular = pow(max(dot(n, halfDir), 0.0), 200.0) / dist;   // shininess = 32

        // Base material color (you can change this)
        vec4 baseColor = vec4(0.6, 0.6, 0.6, 0.) + vec4(lightDir, 0.) * 0.2;

        // Combine lighting
        col = baseColor * (diffuse * 0.9 + 0.15);
        col += vec4(vec3(1.), 0.) * specular * 0.3;
        col /= dist * 0.5;
    }
    if((hit > 3. || hit < 0.)) {
      col += vec4(1.) * max(0., 0.1 / distance(uv, light2D) - 0.3);
    }

    gl_FragColor = col;
}

