    float lightIntensity;
    float shadow = -1.;

    for(int a = 0; a < 1000; a++) {
      if (i >= _i) { break; }
      p = ro + rd * tg;
      float d = obj(p);
      if (abs(d) < 0.001) {
      	if(!hit) {
      		//First hit.
      		hit = true;
          hitPoint = p;
          nv = getNormal(p);
          rd = normalize(light - p);
          lightIntensity = max(0., dot(nv, rd));
          ro = p;
          tg = 0.01;
          d = 0.;
      	} else {
          //Second hit. Calculate shadow
          shadow = 1. / (1. + distance(p, hitPoint));
          break;
        }
      }
      tg += max(0.001, d * 0.7);
      if (tg > 50.0) break;
      i++;
    }
    if(hit) {
