        cos(-to.x), 0.0, sin(-to.x),
        0.0, 1.0, 0.0,
       -sin(-to.x), 0.0, cos(-to.x)
    );

    // Pitch (up/down)
    mat3 rotX = mat3(
        1.0, 0.0, 0.0,
        0.0, cos(to.y), -sin(to.y),
        0.0, sin(to.y), cos(to.y)
    );

    // Combine rotations: Yaw then Pitch
    mat3 rot = rotY * rotX;

    // Ray
    vec3 rd = normalize(vec3(uv, 1.5));
    rd = rot * rd;
    float eta = 1.5;
    gl_FragColor = vec4(rayMarch(ro, rd, 1000, eta), 1.0);
}

