// =============================================
// Marble Marcher-style Fractal SDF
// =============================================

// Helper: Menger fold
void mengerFold(inout vec4 z) {
    float a = min(z.x - z.y, 0.0);
    z.x -= a; z.y += a;
    a = min(z.x - z.z, 0.0);
    z.x -= a; z.z += a;
    a = min(z.y - z.z, 0.0);
    z.y -= a; z.z += a;
}

// Helper: Box DE (final primitive)
float deBox(vec4 p, vec3 s) {
    vec3 a = abs(p.xyz) - s;
    return (min(max(max(a.x, a.y), a.z), 0.0) + length(max(a, 0.0))) / p.w;
}

// Rotations (overloaded for convenience)
void rotX(inout vec4 z, float a) {
    float s = sin(a), c = cos(a);
    z.yz = vec2(c * z.y + s * z.z, c * z.z - s * z.y);
}

void rotZ(inout vec4 z, float a) {
    float s = sin(a), c = cos(a);
    z.xy = vec2(c * z.x + s * z.y, c * z.y - s * z.x);
}

// Main fractal distance estimator
//   p     : point to evaluate (use vec4(p, 1.0) if your raymarcher expects it)
//   iter  : number of iterations (usually 8–20; game uses 16)
//   scale : scaling factor per iteration (>1.0 makes it grow)
//   ang1  : rotation around Z each iteration
//   ang2  : rotation around X each iteration
//   shift : translation applied after scaling
float obj(vec3 pos, int iter, float scale, float ang1, float ang2, vec3 shift) {
    vec4 p = vec4(pos, 1.0);

    for (int i = 0; i < 1000; ++i) {
        if (i >= iter) break;
        p.xyz = abs(p.xyz);           // absolute fold
        rotZ(p, ang1);
        mengerFold(p);
        rotX(p, ang2);
        p *= scale;                   // scale
        p.xyz += shift;               // translate
    }

    return deBox(p, vec3(6.0));       // final box distance
}

float obj(vec3 p) {
	//return length(p) - 1.;
	float t = 0.3 * time;
	float a = 0.2 * time;
	//return obj(p, 13, 1.17, -sin(t), cos(a), vec3(-0.5, 0.2, -0.5));
	return obj(p * 0.5, 6, 2.7, 0.2 * cos(t), 0.4 * cos(a), vec3(-2., sin(t) * 0.2 - 1., -1.));
	//return obj(p, 10, 1.9073, -9.83, -1.16, vec3(-3.508, -3.593, 3.295));
}

vec3 getNormal(vec3 p)
{
    const float eps = 0.001;
    const vec2 h = vec2(eps, 0.0);
    vec3 n = vec3(
        obj(p + h.xyy) - obj(p - h.xyy),
        obj(p + h.yxy) - obj(p - h.yxy),
        obj(p + h.yyx) - obj(p - h.yyx)
    );
    return normalize(n);
}

vec3 background(vec3 rd) {
	return rd;
}

vec3 rayMarch(vec3 ro, vec3 rd, int _i, vec3 light) {
    float tg = 0.0;
    int i = 0;
    vec3 p;
    vec3 hitPoint;
    vec3 nv;
    bool hit = false;
    float lightIntensity;
    float shadow = -1.;

    for(int a = 0; a < 1000; a++) {
      if (i >= _i) { break; }
      p = ro + rd * tg;
      float d = obj(p);
      if (abs(d) < 0.001) {
      	if(!hit) {
      		//First hit.
      		hit = true;
          hitPoint = p;
          nv = getNormal(p);
          rd = normalize(light - p);
          lightIntensity = max(0., dot(nv, rd));
          ro = p;
          tg = 0.01;
          d = 0.;
      	} else {
          //Second hit. Calculate shadow
          shadow = 1. / (1. + distance(p, hitPoint));
          break;
        }
      }
      tg += max(0.001, d * 0.7);
      if (tg > 50.0) break;
      i++;
    }
    if(hit) {
      nv = (abs(nv) + 1.) * 0.5;
    	if(shadow == -1.) {
    		return nv * max(0.1, lightIntensity);
    	} else {
    		return nv * max(0.1, lightIntensity - shadow);
    	}
    } else {
    	return vec3(0.);
    }
}

vec2 normCoord(vec2 c) {
	return (c - resolution / 2.)/ min(resolution.x, resolution.y) * 1.2;
}

void main(void){
    vec2 uv = normCoord(gl_FragCoord.xy);
