        1.0, 0.0, 0.0,
        0.0, cos(to.y), -sin(to.y),
        0.0, sin(to.y), cos(to.y)
    );

    // Combine rotations
    mat3 rot = rotY * rotX;

    // Ray
    vec3 rd = normalize(vec3(uv, 1.5));
    rd = rot * rd;
    gl_FragColor = vec4(rayMarch(ro, rd, 200, light), 1.0);
}

