vec3 rotateVec(vec3 v, float yaw, float pitch) {
  float cy = cos(yaw);
  float sy = sin(yaw);
  float cp = cos(pitch);
  float sp = sin(pitch);

  vec3 pR = vec3(
    v.x,
    cp * v.y - sp * v.z,
    sp * v.y + cp * v.z
  );

  vec3 yR = vec3(
    cy * pR.x - sy * pR.z,
    pR.y,
    sy * pR.x + cy * pR.z
  );

  return yR;
}

float obj(vec3 p) {
	return min(
		length(p.xy - vec2(cos(p.z), sin(p.z))) - 0.1,
		2. - max(abs(p.x), abs(p.y))
	);
}

vec3 getNormal(vec3 p)
{
    const float eps = 0.001;           // smaller = sharper, but can be noisy
    const vec2 h = vec2(eps, 0.0);
    vec3 n = vec3(
        obj(p + h.xyy) - obj(p - h.xyy),
        obj(p + h.yxy) - obj(p - h.yxy),
        obj(p + h.yyx) - obj(p - h.yyx)
    );
    return normalize(n);
}

vec3 refractRay(vec3 ray,vec3 nv,float eta)
{
    float cosTheta = dot(-ray, nv);
    if (cosTheta < 0.0) {
        cosTheta = 0.0;
    }
    float sin2Theta = 1.0 - cosTheta * cosTheta;
    float k = 1.0 - eta * eta * sin2Theta;
    if (k < 0.0) {
        return reflect(ray, nv);
    }
    return normalize(eta * ray + (eta * cosTheta - sqrt(k)) * nv);
}

vec3 background(vec3 rd) {
	return vec3(0.);
}

const float r_f = 50.;
const float r_d = 0.05;

vec3 rayMarch(vec3 ro, vec3 rd, int _i, float eta) {
    float tg = 0.0;
    int i = 0;
    vec3 p;

    for (int a = 0; a < 1000; a++) {
        if(i >= _i) break;
        for (int b = 0; b < 1000; b++) {
            if(i >= _i) break;
            p = ro + rd * tg;
            float d = obj(p);
            if (abs(d) < 0.001) {
            	  if(length(p.xy) < 1.1) {
            	  	//Hit Spool
            	  	vec3 nv = getNormal(p);
            	  	return (1. + 3. * dot(rd, -nv)) * vec3(1., 0.1, 0.05);
            	  }
                break;
            }
            tg += d * 0.8;
            if (tg > 50.0) break;
            i++;
        }
        if (tg > 50.0 || i >= _i) break;
        vec3 nv = (abs(p.x) > abs(p.y)) ?
          vec3(-p.x, cos(p.y * r_f) * r_d, cos(p.z * r_f) * r_d) :
          vec3(cos(p.x * r_f) * r_d, -p.y, cos(p.z * r_f) * r_d);
        nv = normalize(nv);
        rd = reflect(rd, nv);
        ro = p;
        tg = 0.1;
    }

    return background(rd);
}

vec2 normCoord(vec2 c) {
	return (c - resolution / 2.)/ resolution.x * 2.;
}

