    mat3 rot = rotY * rotX;

    // Ray
    vec3 rd = normalize(vec3(uv, 1.5));
    rd = rot * rd;
    float eta = 1.5;
    gl_FragColor = vec4(rayMarch(ro, rd, 100, eta), 1.0);
