vec3 background(vec3 rd) {
	rd = abs(rd);
	float maxi = max(max(rd.x, rd.y), rd.z);
	rd = abs(fract(rd / maxi * 1.) -0.5);
	return vec3(clamp(0.05 / min(min(rd.x, rd.y), rd.z), 0., 1.));
