vec3 rayMarch(vec3 ro, vec3 rd, int _i, float eta) {
	  vec3 ro_orig = ro;
    float tg = 0.0;
    int i = 0;
    vec3 p;
    bool air = true;
    float innerDist = 0.;
    vec3 entryPoint;

    for (int a = 0; a < 1000; a++) {
        if(i >= _i) break;
        for (int b = 0; b < 1000; b++) {
            if(i >= _i) break;
            p = ro + rd * tg;
            float d = obj(p);
            if (abs(d) < 0.001) {
                break;
            }
            float stepSize = air ? d : -d;
            tg += max(0.001, stepSize * 0.4);
            if (tg > 50.0) break;
            i++;
        }
        if (tg > 50.0 || i >= _i) break;
        vec3 nv = getNormal(p);
        if(air) {
        	eta = 1. / eta;
        } else {
        	nv = - nv;
        }
        if(abs(dot(nv, rd)) > rand(gl_FragCoord.xy * fract(time + eta))) {
          rd = refractRay(rd, nv, eta);
          if (dot(rd, nv) < 0.01) {
          	if(air) {
          		entryPoint = p;
          	} else {
          		innerDist += distance(entryPoint, p);
          	}
            air = !air;
          }
        } else {
        	rd = reflect(rd, nv);
        }
        ro = p;
        tg = 0.1;
    }

    return (background(rd) - innerDist) / distance(p, ro_orig) * 3.;
}

