        1.0, 0.0, 0.0,
        0.0, cos(to.y), -sin(to.y),
        0.0, sin(to.y), cos(to.y)
    );

    // Combine rotations: Yaw then Pitch
    mat3 rot = rotY * rotX;

    // Ray
    vec3 rd = normalize(vec3(uv, 1.5));
    rd = rot * rd;
    float eta = 1.5;
    float chroma = 0.1;
    float r = rayMarch(ro, rd, 100, eta).r;
    float g = rayMarch(ro, rd, 100, eta + chroma).g;
    float b = rayMarch(ro, rd, 100, eta + 2. * chroma).b;
