const float PI = 3.1415926;
const float layers = 20.;

float rand(vec2 n) {return fract(sin(dot(n, vec2(12.9898, 4.1414))) * 43758.5453);}

float noize(vec2 pos) {
	return mix(
		mix(rand(floor(pos)), rand(vec2(ceil(pos.x), floor(pos.y))), fract(pos.x)),
		mix(rand(vec2(floor(pos.x), ceil(pos.y))), rand(ceil(pos)), fract(pos.x)),
	  fract(pos.y)
	);
}

vec3 rotateVec(vec3 v, float yaw, float pitch) {
  float cy = cos(yaw);
  float sy = sin(yaw);
  float cp = cos(pitch);
  float sp = sin(pitch);

  vec3 pR = vec3(
    v.x,
    cp * v.y - sp * v.z,
    sp * v.y + cp * v.z
  );

  vec3 yR = vec3(
    cy * pR.x - sy * pR.z,
    pR.y,
    sy * pR.x + cy * pR.z
  );

  return yR;
}

vec2 normCoord(vec2 c) {
	return (c - resolution / 2.)/ resolution.y * 2.;
}

void main(void) {
	float t = time * 0.5;
	vec2 uv = normCoord(gl_FragCoord.xy).yx;
  vec3 ray = rotateVec(vec3(uv, 1.), -t, 0.);

	vec3 cam = 1.3 * vec3(sin(t), 0., cos(t));
	t = time * 0.5;

	for(float z = -1.; z <= 1.; z += 2./layers) {
    float r = noize(vec2(z * layers, t));
    float w = max(0., fract(abs(z) - time / 1.875) - 0.4);

    float a = -(cam.z + z)/ray.z;
	  vec3 p = cam + a * ray;
		gl_FragColor +=
		max(vec4(0.),
			w *
			vec4(max(z * 0.5, 0.), max(-z * 0.5, 0.), 1., 0.) *
			(0.01 / abs(length(p.xy) - 0.3 * (r + 0.2)))
		);
	}
	gl_FragColor += max(vec4(0.), vec4(length(gl_FragColor)) - 1.);

	const float rad = 3.;
	vec4 bloom = vec4(0.);
	for(float x = -rad; x <= rad; x ++) {
		for(float y = -rad; y <= rad; y ++) {
		  bloom += texture2D(backbuffer, (gl_FragCoord.xy + 5. * vec2(x,y))/resolution);
	  }
	}
	gl_FragColor += bloom / pow(2. * rad + 1., 2.) * 0.9;
