const float PI = 3.1415926;

const int octaves = 3;
const float lacunarity = 0.5;
const float persistance = 0.5;

vec2 rotateVec(vec2 v, float b) {
	return vec2(cos(b) * v.x + sin(b) * v.y, cos(b) * v.y - sin(b) * v.x);
}

//float rand(vec2 n) {return fract(sin(dot(n, vec2(12.9898, 4.1414))) * 43758.5453);}
float rand(vec2 n) {return fract((dot(n, vec2(1.46, 7.52))));}

float noize(vec2 pos) {
	return mix(
		mix(rand(floor(pos)), rand(vec2(ceil(pos.x), floor(pos.y))), fract(pos.x)),
		mix(rand(vec2(floor(pos.x), ceil(pos.y))), rand(ceil(pos)), fract(pos.x)),
	  fract(pos.y)
	);
}

float layeredNoize(vec2 pos, int o) {
	pos = rotateVec(pos, 2.4);
	float layered = 0.0;
	for(int layer = 1; layer <= 10; layer ++) {
    if(layer > o) break;
    layered += noize(pos) * pow(persistance, float(layer));
    pos = rotateVec(pos/lacunarity, 2.4);
	}
	return layered;
}

void main(void) {
	vec2 uv = (gl_FragCoord.xy - resolution / 2.)/ resolution.x * 2.;
  uv.y /= abs(uv.x);
  float xo = uv.x;
  uv.x = abs(uv.x);
  uv.x = log(uv.x);
  float d = abs(uv.x);
  uv.x += sign(xo) * 1000.;
  uv.x -= time * 2.;

  vec3 fragColor = vec3(0.);

  if(abs(uv.y) < 30.) {
	  fragColor = 0.5 * sin(vec3(layeredNoize(uv * 0.01 + 1200., 3) * 20., layeredNoize(uv * 0.02 + 300., 3)* 30., layeredNoize(uv * 0.03 + 700., 3) * 80.)) + 0.5;
	  fragColor *= smoothstep(0.4, 0.6, layeredNoize(uv * vec2(0.3, 1.), 7));
	  fragColor *= step(fract(uv.y * 30.), 0.9) * step(fract(uv.x * 30.), 0.3);
  }
  const float rad = 5.;
	vec4 bloom = vec4(0.);
	for(float x = -rad; x <= rad; x ++) {
		for(float y = -rad; y <= rad; y ++) {
		  bloom += texture2D(backbuffer, ((gl_FragCoord.xy) + 5. * vec2(x,y))/resolution) / (length(vec2(x,y)) + 0.1);
	  }
	}
	fragColor += bloom.xyz/(pow(rad, 2.) * 1.8);
	fragColor += (d * 0.05) - 0.1;
  gl_FragColor = vec4(fragColor, 1.);
}

