float N21(vec2 p) {
  vec3 a = fract(vec3(p.xyx) * vec3(213.897, 653.453, 253.098));
  a += dot(a, a.yzx + 79.76);
  return fract((a.x + a.y) * a.z);
}

vec3 p(float v) {
	v = N21(vec2(v));
	v *= 6.283185307179;
	return 0.5 + 0.5 * vec3(cos(v - 1.7), cos(v - 3.), -1.);
}

vec3 rotateVec(vec3 v, float yaw, float pitch) {
  float cy = cos(yaw);
  float sy = sin(yaw);
  float cp = cos(pitch);
  float sp = sin(pitch);

  vec3 pR = vec3(
    v.x,
    cp * v.y - sp * v.z,
    sp * v.y + cp * v.z
  );

  vec3 yR = vec3(
    cy * pR.x - sy * pR.z,
    pR.y,
    sy * pR.x + cy * pR.z
  );

  return yR;
}

vec2 normCoord(vec2 c) {
	return (c - resolution / 2.)/ resolution.x * 2.;
}

float obj(vec3 p) {
	return -(p.z + p.x + p.y)/ 1.75;//distance(p, vec3(260.)) - 240.;
}

vec3 gridMarch(vec3 ro, vec3 rd, int maxSteps) {
	vec3 ta;
	float m;
	float s = 0.001;
	vec3 p = ro;

	for(int i = 0; i < 1000; i++) {
    if(i >= maxSteps) {break;}
		// find next planes in xyz
		vec3 nx_planes = floor(p) + max(vec3(0.), sign(rd));
		// find additional vector lengths to reach them
		ta = (nx_planes - p) / rd;
    // get minimum
    m = min(ta.x, min(ta.y, ta.z));
    // march by minimum
		s += m + 0.001;

		p = (ro + s * rd);
		// get midpoint of cube
		vec3 mp = floor(p) + 0.5;
		// get min distance to obj
		float od = obj(mp);
		// inside check
		if(od < 0.) break;
		// if further than sqrt(3) skip ahead
		if(od > 1.75) {
			s += od - 1.75;
			p = (ro + s * rd);
		}
		// infinity break
		if(s > 1000.) {return vec3(1000.);}
	}

	return p;
}

vec3 getNv(vec3 p, vec3 rd) {
	vec3 d = abs(p - floor(p + 0.5));
	float m = min(d.x, min(d.y, d.z));
	return vec3(m == d.x, m == d.y, m == d.z);// * sign(rd);
}

void main(void) {
	float t = time * 0.4;
	vec2 to = -0.5 * PI * vec2(clamp(mod(t, 3.) - 1., 0.001, 0.999), clamp(abs(mod(t, 3.)-1.5) - 0.5, 0.001, 0.999));
	//vec2 to = -touch / resolution * 0.5 * PI;
	//vec3 ro = vec3(0.5);
  //vec3 rd = normalize(vec3(normCoord(gl_FragCoord.xy) * FOV, 1.));
  vec3 ro = vec3(normCoord(gl_FragCoord.xy) * FOV, -100.);
  vec3 rd = vec3(0., 0., 1.);
  ro = rotateVec(ro, to.x, to.y) + 0.5;
  rd = rotateVec(rd, to.x, to.y);

  vec3 gm = gridMarch(ro, rd, 200);

  //Infinity check
  if(gm == vec3(1000.)) {return;}

  vec3 nv = getNv(gm, rd).yzx;
  float side = length(nv * vec3(1., 2., 3.));
  side = floor(t) + mod(side - floor(t), 3.);

  gl_FragColor = vec4(p(side), 1.);
}

