vec4 gridMarch(vec3 ro, vec3 rd, int maxSteps, vec3 target) {
	bool targetMode = target != vec3(0.);
	vec3 ta;
	float m;
	float s = 0.001;
	vec3 p = ro;

	int i = 0;
  for(int i = 0; i < 1000; i ++) {
	  if((i < maxSteps && (!targetMode || distance(target, p) > 2.)) == false) {break;}
		// find next planes in xyz
		vec3 nx_planes = floor(p) + max(vec3(0.), sign(rd));
		// find additional vector lengths to reach them
		ta = (nx_planes - p) / rd;
    // get minimum
    m = min(ta.x, min(ta.y, ta.z));
    // march by minimum
		s += m + 0.001;

		p = (ro + s * rd);
		// get midpoint of cube
		vec3 mp = floor(p) + 0.5;
