void main(void) {
	float z = time * 10.;
	vec3 ro = posByZ(z);
	vec2 uv = normCoord(gl_FragCoord.xy);
  vec3 rd = normalize(vec3(uv * FOV, 1.));
  vec2 to = -normCoord(touch) * 4.;
  rd = rotateVec(rd, to.x, to.y);
  vec4 gm = gridMarch(ro, rd, 180, vec3(0.));

  vec3 light = posByZ(z + 10.);

  //Infinity check
  if(gm.xyz != vec3(1000.)) {
    vec3 nv = getNv(gm.xyz, rd);

    vec2 tc;
    if(nv.y == 0.) {
  	  tc.y = fract(gm.y);
    } else {
    	tc.y = fract(gm.z);
    }
    if(nv.x == 0.) {
    	tc.x = fract(gm.x);
    } else {
    	tc.x = fract(gm.z);
    }
    float shade = 0.3;
    vec3 lightDir = normalize(light - gm.xyz);
    if(distance(gridMarch(gm.xyz, lightDir, 180, light).xyz, light) < 2.) {
    	shade = 1.;
