void dimensionLayer(vec3 ro, vec3 rd, float beat) {
	//beat = 0.;
	float dir = sign(rd.z);
	float closeLayer = floor(ro.z + 0.5) + 0.5*dir;
  float z = closeLayer;
	for(int i = 0; i < 1000; i++) {
